58	static int64_t sys_shutdown(void) {
59	    /* QEMU ACPI PM1a control — works on both BIOS and UEFI QEMU */
60	    outw(0x604, 0x2000);
61	    /* QEMU PIIX4 legacy fallback */
62	    outw(0xB004, 0x2000);
63	    /* QEMU microvm / virt fallback */
64	    outw(0x4004, 0x3400);
