69	static int64_t sys_reboot(void) {
70	    /* ACPI/PCIe reset register — works on BIOS and UEFI QEMU */
71	    outb(0xCF9, 0x06);
72	    /* PS/2 keyboard controller reset (BIOS fallback) */
73	    uint8_t val;
74	    do { __asm__ volatile ("inb %1, %0" : "=a"(val) : "Nd"((uint16_t)0x64)); }
75	    while (val & 0x02);
76	    outb(0x64, 0xFE);
77	    for (;;) __asm__ volatile ("cli; hlt");
