139	/* SYS_YIELD: voluntarily give up CPU, scheduler picks next process */
140	static int64_t sys_yield(void) {
141	    if (!current_proc) return ESYS_OK;
142	    process_t *next = sched_pick();
143	    if (next && next != current_proc)
144	        proc_switch(next);
145	    return ESYS_OK;
146	}
