153	/*
154	 * SYS_SPAWN: rdi=entry_fn_ptr, rsi=name_ptr, rdx=priority
155	 * Creates and immediately enqueues a new Ring-1 process.
156	 * Returns new pid on success, negative on error.
157	 */
158	static int64_t sys_spawn(uint64_t entry, uint64_t name_ptr, uint64_t priority) {
159	    if (!entry) return ESYS_BADARG;
160	    const char *name = name_ptr ? (const char *)name_ptr : "proc";
161	    process_t *p = proc_create((void (*)(void))entry, name,
162	                                RING_SERVICE, SCHED_QUANTUM_BASE, (uint32_t)priority);
163	    if (!p) return ESYS_NOMEM;
164	    proc_wake(p);
165	    return (int64_t)p->pid;
166	}
167	
168	/*
169	 * SYS_FORK: duplicate calling process.
170	 * Returns child pid to parent, 0 to child.
171	 */
172	static int64_t sys_fork(void) {
173	    if (!current_proc) return ESYS_BADARG;
174	    process_t *child = proc_fork(current_proc);
175	    if (!child) return ESYS_NOMEM;
176	    /* Child gets 0 in rax after iretq — set it in child's saved context */
177	    /* The saved rax sits in the int_frame_t on child's stack; we zero it
178	     * by adjusting the iretq frame that ctx_switch will restore.         */
179	    child->ctx.rip = current_proc->ctx.rip;
180	    proc_wake(child);
181	    return (int64_t)child->pid;   /* parent sees child pid */
182	}
