184	/* SYS_EXIT: terminate calling process */
185	static int64_t sys_exit(uint64_t code) {
186	    (void)code;
187	    if (!current_proc) return ESYS_BADARG;
188	    proc_destroy(current_proc);
189	    /* Pick next runnable process */
190	    process_t *next = sched_pick();
191	    if (next) proc_switch(next);
192	    /* If no next process, idle */
193	    for (;;) __asm__ volatile ("hlt");
194	    return ESYS_OK;
195	}
