197	/* SYS_KILL: destroy a process by pid */
198	static int64_t sys_kill(uint64_t pid) {
199	    if (!pid) return ESYS_BADARG;
200	    process_t *p = proc_by_pid((uint32_t)pid);
201	    if (!p) return ESYS_NOPROC;
202	    /* Cannot kill the idle kernel task (pid 0 guard above) */
203	    proc_destroy(p);
204	    return ESYS_OK;
205	}
