207	/*
208	 * SYS_WAIT: busy-spin yielding until target pid exits.
209	 * A real implementation would block; for now we yield repeatedly.
210	 */
211	static int64_t sys_wait(uint64_t pid) {
212	    if (!pid) return ESYS_BADARG;
213	    while (proc_by_pid((uint32_t)pid) != NULL)
214	        sys_yield();
215	    return ESYS_OK;
216	}
