218	/* SYS_SLEEP: yield for at least N scheduler ticks */
219	static int64_t sys_sleep(uint64_t ticks) {
220	    uint64_t wake = sched_ticks + ticks;
221	    while (sched_ticks < wake)
222	        sys_yield();
223	    return ESYS_OK;
224	}
