383	/* SYS_PUTCELL: draw one character cell at (col, row) without moving the
384	 * global cursor.  packed = char | (attr << 8).  Works on both display paths. */
385	static int64_t sys_putcell(uint64_t col, uint64_t row, uint64_t packed) {
386	    char    ch   = (char)(packed & 0xFF);
387	    uint8_t attr = (uint8_t)((packed >> 8) & 0xFF);
388	
389	    /* Snapshot and restore every piece of mutable display state */
390	    size_t  sc = vga_col, sr = vga_row;
391	    uint8_t sa = vga_color;
392	
393	    vga_color = attr;
394	    /* Directly set position — bypass vga_goto's clamping side-effects */
395	    vga_col = (size_t)col;
396	    vga_row = (size_t)row;
397	
398	    /* Draw the character in-place via the path-aware renderer */
399	    extern bool gop_available;
400	    if (gop_available) {
401	        /* GOP: render glyph directly at pixel position, never advance cursor */
402	        extern void gop_draw_glyph(uint32_t px, uint32_t py,
403	                                   const uint8_t *bitmap, uint32_t rows,
404	                                   uint32_t fg, uint32_t bg);
405	        extern const uint8_t font8x16[256][16];
406	        extern gop_info_t gop_fb;
407	
408	        /* Translate VGA palette attr to 32-bit GOP colours */
409	        static const uint8_t pal[16][3] = {
410	            {0x00,0x00,0x00},{0x00,0x00,0xAA},{0x00,0xAA,0x00},{0x00,0xAA,0xAA},
411	            {0xAA,0x00,0x00},{0xAA,0x00,0xAA},{0xAA,0x55,0x00},{0xAA,0xAA,0xAA},
412	            {0x55,0x55,0x55},{0x55,0x55,0xFF},{0x55,0xFF,0x55},{0x55,0xFF,0xFF},
413	            {0xFF,0x55,0x55},{0xFF,0x55,0xFF},{0xFF,0xFF,0x55},{0xFF,0xFF,0xFF},
414	        };
415	        uint8_t fi = attr & 0x0F, bi = (attr >> 4) & 0x0F;
416	        uint32_t fg = ((uint32_t)pal[fi][0] << gop_fb.red_pos)
417	                    | ((uint32_t)pal[fi][1] << gop_fb.green_pos)
418	                    | ((uint32_t)pal[fi][2] << gop_fb.blue_pos);
419	        uint32_t bg = ((uint32_t)pal[bi][0] << gop_fb.red_pos)
420	                    | ((uint32_t)pal[bi][1] << gop_fb.green_pos)
421	                    | ((uint32_t)pal[bi][2] << gop_fb.blue_pos);
422	
423	        gop_draw_glyph((uint32_t)col * 8u, (uint32_t)row * 16u,
424	                       font8x16[(uint8_t)ch], 16, fg, bg);
425	    } else {
426	        /* VGA text mode: write directly to text RAM */
427	        volatile uint16_t *vram = (volatile uint16_t *)0xB8000;
428	        vram[row * 80 + col] = (uint16_t)(uint8_t)ch | ((uint16_t)attr << 8);
429	    }
430	
431	    vga_col   = sc;
432	    vga_row   = sr;
433	    vga_color = sa;
434	    return ESYS_OK;
435	}
436	
437	static int64_t sys_setcursor(uint64_t col, uint64_t row) {
438	    vga_goto(col, row);
439	    return ESYS_OK;
440	}
441	
442	/* SYS_PS: fill caller buf with proc_snap_t entries for all live processes */
443	static int64_t sys_ps(uint64_t buf_ptr, uint64_t max_entries) {
444	    if (!buf_ptr || max_entries == 0) return ESYS_BADARG;
445	    return (int64_t)proc_snapshot((proc_snap_t *)buf_ptr, (int)max_entries);
446	}
447	
448	/* ── Dispatch ─────────────────────────────────────────────────────────────── */
449	void syscall_dispatch(int_frame_t *frame) {
450	    uint64_t num  = frame->rax;
451	    uint64_t arg1 = frame->rdi;
452	    uint64_t arg2 = frame->rsi;
453	    uint64_t arg3 = frame->rdx;
454	    uint64_t arg4 = frame->rcx;
455	    uint64_t arg5 = frame->r8;
456	
457	    int64_t ret;
458	    switch (num) {
459	        /* I/O */
460	        case SYS_PRINT:     ret = sys_print(arg1, arg2);             break;
461	        case SYS_CLEAR:     ret = sys_clear();                        break;
462	        case SYS_NEWLINE:   ret = sys_newline();                      break;
463	        case SYS_READ_MEM:  ret = sys_read_mem(arg1);                 break;
464	        case SYS_CPU_MODEL: ret = sys_cpu_model(arg1, arg2);          break;
465	        case SYS_SHUTDOWN:  ret = sys_shutdown();                     break;
466	        case SYS_REBOOT:    ret = sys_reboot();                       break;
467	        case SYS_GETCHAR:   ret = sys_getchar();                      break;
468	        case SYS_GETKEY:    ret = sys_getkey();                       break;
469	        case SYS_CHDIR:     ret = sys_chdir(arg1);                    break;
470	        case SYS_GETCWD:    ret = sys_getcwd(arg1, arg2);             break;
471	        /* Process */
472	        case SYS_YIELD:     ret = sys_yield();                        break;
473	        case SYS_GETPID:    ret = sys_getpid();                       break;
474	        case SYS_SPAWN:     ret = sys_spawn(arg1, arg2, arg3);        break;
475	        case SYS_FORK:      ret = sys_fork();                         break;
476	        case SYS_EXIT:      ret = sys_exit(arg1);                     break;
477	        case SYS_KILL:      ret = sys_kill(arg1);                     break;
478	        case SYS_WAIT:      ret = sys_wait(arg1);                     break;
479	        case SYS_SLEEP:     ret = sys_sleep(arg1);                    break;
480	        case SYS_GETPNAME:  ret = sys_getpname(arg1, arg2, arg3);     break;
481	        /* JS */
482	        case SYS_JS_EXEC:        ret = sys_js_exec(arg1);              break;
483	        /* Time */
484	        case SYS_TIME:           ret = sys_time();                     break;
485	        case SYS_CLOCK_GETTIME:  ret = sys_clock_gettime(arg1, arg2);  break;
486	        /* Filesystem */
487	        case SYS_FS_OPEN:    ret = sys_fs_open(arg1, arg2, arg3);    break;
488	        case SYS_FS_CLOSE:   ret = sys_fs_close(arg1);               break;
489	        case SYS_FS_READ:    ret = sys_fs_read(arg1, arg2, arg3);    break;
490	        case SYS_FS_WRITE:   ret = sys_fs_write(arg1, arg2, arg3);   break;
491	        case SYS_FS_SEEK:    ret = sys_fs_seek(arg1, arg2, arg3);    break;
492	        case SYS_FS_STAT:    ret = sys_fs_stat(arg1, arg2);          break;
493	        case SYS_FS_FSTAT:   ret = sys_fs_fstat(arg1, arg2);         break;
494	        case SYS_FS_READDIR: ret = sys_fs_readdir(arg1, arg2, arg3); break;
495	        case SYS_FS_MKDIR:   ret = sys_fs_mkdir(arg1, arg2);         break;
496	        case SYS_FS_UNLINK:  ret = sys_fs_unlink(arg1);              break;
497	        case SYS_FS_CREAT:   ret = sys_fs_creat(arg1, arg2);         break;
498	        case SYS_PS:           ret = sys_ps(arg1, arg2);               break;
499	        case SYS_GETKEY_NB:    ret = (int64_t)keyboard_getkey_nonblock(); break;
500	        case SYS_DISPLAY_MODE: ret = sys_display_mode();                          break;
501	        case SYS_PUTCELL:      ret = sys_putcell(arg1, arg2, arg3);              break;
502	        case SYS_SETCURSOR:    ret = sys_setcursor(arg1, arg2);                  break;
503	        case SYS_FB_INFO:      ret = sys_fb_info(arg1);                          break;
504	        case SYS_FB_FILLRECT:  ret = sys_fb_fillrect(arg1, arg2, arg3, arg4, arg5); break;
505	        case SYS_BEEP:
506	            vb_beep((uint32_t)arg1, (uint32_t)arg2);
507	            ret = ESYS_OK;
508	            break;
509	        default:
510	            ret = ESYS_BADNUM;
511	            kprint("[SYSCALL] unknown #"); kprint_uint64(num); kprint("\n");
512	            break;
513	    }
514	
515	    frame->rax = (uint64_t)ret;
516	}
517	
518	/* ── IDT hook ─────────────────────────────────────────────────────────────── */
519	void syscall_init(void) {
520	    idt[0x80].type_attr = 0xAE;   /* present, DPL=1, 64-bit interrupt gate */
521	}
