290	    js_State *J = js_newstate(NULL, NULL, JS_STRICT);
291	    if (!J) { kprint("[JS] failed to create state\n"); return; }
292	
293	    js_setreport(J, js_report_fn);
294	
295	    /* I/O */
296	    js_newcfunction(J, js_fn_print,       "print",       1); js_setglobal(J, "print");
297	    js_newcfunction(J, js_fn_println,     "println",     1); js_setglobal(J, "println");
298	    js_newcfunction(J, js_fn_readline,    "readline",    0); js_setglobal(J, "readline");
299	    js_newcfunction(J, js_fn_getchar,          "getChar",        0); js_setglobal(J, "getChar");
300	    js_newcfunction(J, js_fn_getkey_nonblock,  "getKeyNonBlock", 0); js_setglobal(J, "getKeyNonBlock");
301	    js_newcfunction(J, js_fn_getticks,         "getTicks",       0); js_setglobal(J, "getTicks");
302	    js_newcfunction(J, js_fn_getgametick,      "getGameTick",    0); js_setglobal(J, "getGameTick");
303	
304	    /* Terminal control */
305	    js_newcfunction(J, js_fn_setcursor,   "setCursor",   2); js_setglobal(J, "setCursor");
306	    js_newcfunction(J, js_fn_setcolor,    "setColor",    2); js_setglobal(J, "setColor");
307	    js_newcfunction(J, js_fn_screenwidth, "screenWidth",  0); js_setglobal(J, "screenWidth");
308	    js_newcfunction(J, js_fn_screenheight,"screenHeight", 0); js_setglobal(J, "screenHeight");
309	    js_newcfunction(J, js_fn_clearscreen, "clearScreen",  0); js_setglobal(J, "clearScreen");
310	    js_newcfunction(J, js_fn_printat,     "printAt",     3); js_setglobal(J, "printAt");
311	    js_newcfunction(J, js_fn_vgapoke,    "vgaPoke",     4); js_setglobal(J, "vgaPoke");
312	    js_newcfunction(J, js_fn_hidecursor, "hideCursor",  0); js_setglobal(J, "hideCursor");
313	    js_newcfunction(J, js_fn_showcursor, "showCursor",  0); js_setglobal(J, "showCursor");
314	
315	    /* CWD */
316	    js_newcfunction(J, js_fn_chdir,  "chdir",  1); js_setglobal(J, "chdir");
317	    js_newcfunction(J, js_fn_getcwd, "getcwd", 0); js_setglobal(J, "getcwd");
318	
319	    /* Process info */
320	    js_newcfunction(J, js_fn_getprocesslist, "getProcessList", 0); js_setglobal(J, "getProcessList");
321	
322	    /* Filesystem */
323	    js_newcfunction(J, js_fn_open,    "fsOpen",    2); js_setglobal(J, "fsOpen");
324	    js_newcfunction(J, js_fn_close,   "fsClose",   1); js_setglobal(J, "fsClose");
325	    js_newcfunction(J, js_fn_read,    "fsRead",    2); js_setglobal(J, "fsRead");
326	    js_newcfunction(J, js_fn_write,   "fsWrite",   2); js_setglobal(J, "fsWrite");
327	    js_newcfunction(J, js_fn_readdir, "fsReaddir", 2); js_setglobal(J, "fsReaddir");
328	    js_newcfunction(J, js_fn_stat,    "fsStat",    1); js_setglobal(J, "fsStat");
329	    js_newcfunction(J, js_fn_mkdir,   "fsMkdir",   1); js_setglobal(J, "fsMkdir");
330	    js_newcfunction(J, js_fn_unlink,  "fsUnlink",  1); js_setglobal(J, "fsUnlink");
331	    js_newcfunction(J, js_fn_creat,   "fsCreat",   1); js_setglobal(J, "fsCreat");
332	
333	    /* Inject signal library into every state before the app runs */
334	    if (js_dostring(J, js_signal_prelude)) {
335	        kprint("[JS] signal prelude failed\n");
336	    }
337	
338	    if (js_dostring(J, source)) {
339	        /* error already reported via js_report_fn */
340	    }
341	
342	    js_freestate(J);
343	}
