/*
 * js_runtime.c — MuJS engine integration for NephilimOS
 *
 * Compiles MuJS via the one.c amalgamation (with our port header),
 * then provides js_runtime_run() which:
 *   1. Creates a JS state
 *   2. Registers C→JS bindings (print, readline, etc.)
 *   3. Runs a JS source string
 *   4. Tears down the state
 */

/* Pull in the port shim before any MuJS header */
#include "../external/include/mujs/mujs_port.h"
/* Compile the entire MuJS engine as one translation unit */
#include "../external/include/mujs/one.c"

/* Signal library — injected into every JS state before the app source */
static const char js_signal_prelude[] =
#include "../userland/signal.js.h"
;

#include <js_runtime.h>
#include <vga.h>
#include <keyboard.h>
#include <timer.h>
#include <fs.h>
#include <process.h>
#include <string.h>

/* keyboard_getkey is declared in keyboard.h — use it for raw key input */

/* ── I/O bindings ─────────────────────────────────────────────────────────── */

static void js_fn_print(js_State *J) {
    const char *s = js_tostring(J, 1);
    kprint(s);
    js_pushundefined(J);
}

static void js_fn_println(js_State *J) {
    const char *s = js_tostring(J, 1);
    kprint(s);
    kprint("\n");
    js_pushundefined(J);
}

static void js_fn_readline(js_State *J) {
    static char buf[256];
    int i = 0;
    buf[0] = '\0';
    for (;;) {
        char c = keyboard_getchar();
        if (c == '\n') { kprint("\n"); break; }
        if ((c == '\b' || c == 0x7F) && i > 0) { i--; kprint("\b \b"); continue; }
        if (c >= 32 && c <= 126 && i < 255) {
            buf[i++] = c;
            char tmp[2] = { c, '\0' };
            kprint(tmp);
        }
    }
    buf[i] = '\0';
    js_pushstring(J, buf);
}

/* ── Filesystem bindings ──────────────────────────────────────────────────── */

/* open(path, flags) → fd  (flags: "r"=O_RDONLY, "w"=O_WRONLY|O_CREAT|O_TRUNC,
 *                                  "a"=O_WRONLY|O_CREAT|O_APPEND, "r+"=O_RDWR) */
static void js_fn_open(js_State *J) {
    const char *path  = js_tostring(J, 1);
    const char *mode  = js_tostring(J, 2);
    int flags;
    if (mode[0] == 'w') flags = O_WRONLY | O_CREAT | O_TRUNC;
    else if (mode[0] == 'a') flags = O_WRONLY | O_CREAT | O_APPEND;
    else if (mode[0] == 'r' && mode[1] == '+') flags = O_RDWR;
    else flags = O_RDONLY;
    int fd = vfs_open(path, flags, 0644);
    js_pushnumber(J, (double)fd);
}

/* close(fd) */
static void js_fn_close(js_State *J) {
    int fd = (int)js_tonumber(J, 1);
    vfs_close(fd);
    js_pushundefined(J);
}

/* read(fd, len) → string (or null on EOF/error) */
static void js_fn_read(js_State *J) {
    int fd   = (int)js_tonumber(J, 1);
    int len  = (int)js_tonumber(J, 2);
    if (len <= 0 || len > 4096) len = 4096;
    static char buf[4097];
    int n = vfs_read(fd, buf, (size_t)len);
    if (n <= 0) { js_pushnull(J); return; }
    buf[n] = '\0';
    js_pushstring(J, buf);
}

/* write(fd, str) → bytes written */
static void js_fn_write(js_State *J) {
    int fd        = (int)js_tonumber(J, 1);
    const char *s = js_tostring(J, 2);
    int n = vfs_write(fd, s, strlen(s));
    js_pushnumber(J, (double)n);
}

/* readdir(fd, index) → {ino, name} or null */
static void js_fn_readdir(js_State *J) {
    int fd    = (int)js_tonumber(J, 1);
    int index = (int)js_tonumber(J, 2);
    fs_dirent_t de;
    int r = vfs_readdir(fd, (uint32_t)index, &de);
    if (r != FS_OK) { js_pushnull(J); return; }
    js_newobject(J);
    js_pushnumber(J, (double)de.inode); js_setproperty(J, -2, "ino");
    js_pushstring(J, de.name);          js_setproperty(J, -2, "name");
}

/* stat(path) → {ino, mode, size, mtime} or null */
static void js_fn_stat(js_State *J) {
    const char *path = js_tostring(J, 1);
    fs_stat_t st;
    int r = vfs_stat(path, &st);
    if (r != FS_OK) { js_pushnull(J); return; }
    js_newobject(J);
    js_pushnumber(J, (double)st.st_ino);   js_setproperty(J, -2, "ino");
    js_pushnumber(J, (double)st.st_mode);  js_setproperty(J, -2, "mode");
    js_pushnumber(J, (double)st.st_size);  js_setproperty(J, -2, "size");
    js_pushnumber(J, (double)st.st_mtime); js_setproperty(J, -2, "mtime");
}

/* mkdir(path) → 0 on success, negative on error */
static void js_fn_mkdir(js_State *J) {
    const char *path = js_tostring(J, 1);
    int r = vfs_mkdir(path, 0755);
    js_pushnumber(J, (double)r);
}

/* unlink(path) → 0 on success, negative on error */
static void js_fn_unlink(js_State *J) {
    const char *path = js_tostring(J, 1);
    int r = vfs_unlink(path);
    js_pushnumber(J, (double)r);
}

/* creat(path) → fd */
static void js_fn_creat(js_State *J) {
    const char *path = js_tostring(J, 1);
    int r = vfs_creat(path, 0644);
    js_pushnumber(J, (double)r);
}

/* ── CWD bindings ─────────────────────────────────────────────────────────── */

extern char kernel_cwd[256];

/* chdir(path) → 0 on success, -1 on error */
static void js_fn_chdir(js_State *J) {
    const char *path = js_tostring(J, 1);
    /* Validate via vfs_open, then update kernel_cwd */
    int fd = vfs_open(path, O_RDONLY, 0);
    if (fd < 0) { js_pushnumber(J, -1.0); return; }
    vfs_close(fd);
    size_t i = 0;
    while (path[i] && i < sizeof(kernel_cwd) - 1) { kernel_cwd[i] = path[i]; i++; }
    kernel_cwd[i] = '\0';
    js_pushnumber(J, 0.0);
}

/* getcwd() → string */
static void js_fn_getcwd(js_State *J) {
    js_pushstring(J, kernel_cwd);
}

/* ── Terminal control bindings ────────────────────────────────────────────── */

/* getTicks() → current PIT tick count (increments at 100 Hz) */
static void js_fn_getticks(js_State *J) {
    js_pushnumber(J, (double)timer_ticks);
}

/* getGameTick() → ~10 Hz game ticks derived from timer_ticks (100 Hz PIT) */
static void js_fn_getgametick(js_State *J) {
    js_pushnumber(J, (double)(timer_ticks / 10));
}

/* getChar() → integer key code (blocking) */
static void js_fn_getchar(js_State *J) {
    int k = keyboard_getkey();
    js_pushnumber(J, (double)k);
}

/* getKeyNonBlock() → key code if pending, -1 if none */
static void js_fn_getkey_nonblock(js_State *J) {
    int k = keyboard_getkey_nonblock();
    js_pushnumber(J, (double)k);
}

/* setCursor(col, row) — move print position without writing anything */
static void js_fn_setcursor(js_State *J) {
    int col = (int)js_tonumber(J, 1);
    int row = (int)js_tonumber(J, 2);
    vga_goto((size_t)col, (size_t)row);
    js_pushundefined(J);
}

/* setColor(fg, bg) — set VGA color attribute (0-15 each) */
static void js_fn_setcolor(js_State *J) {
    int fg = (int)js_tonumber(J, 1);
    int bg = (int)js_tonumber(J, 2);
    vga_color = VGA_COLOR(fg & 0xF, bg & 0xF);
    js_pushundefined(J);
}

/* screenWidth() / screenHeight() */
static void js_fn_screenwidth(js_State *J)  { js_pushnumber(J, VGA_WIDTH);  }
static void js_fn_screenheight(js_State *J) { js_pushnumber(J, VGA_HEIGHT); }

/* clearScreen() — same as SYS_CLEAR */
static void js_fn_clearscreen(js_State *J) {
    vga_clear();
    js_pushundefined(J);
}

/* printAt(col, row, str) — move cursor then print */
static void js_fn_printat(js_State *J) {
    int col        = (int)js_tonumber(J, 1);
    int row        = (int)js_tonumber(J, 2);
    const char *s  = js_tostring(J, 3);
    vga_goto((size_t)col, (size_t)row);
    kprint(s);
    js_pushundefined(J);
}

/*
 * vgaPoke(col, row, charCode, attr)
 * Write directly to VGA_ADDR — zero cursor movement, zero scroll risk.
 * attr = (bg << 4) | fg,  both 0-15.
 */
static void js_fn_vgapoke(js_State *J) {
    int col  = (int)js_tonumber(J, 1);
    int row  = (int)js_tonumber(J, 2);
    int ch   = (int)js_tonumber(J, 3);
    int attr = (int)js_tonumber(J, 4);
    if (col < 0 || col >= VGA_WIDTH || row < 0 || row >= VGA_HEIGHT)
        { js_pushundefined(J); return; }
    VGA_ADDR[row * VGA_WIDTH + col] = (uint16_t)((attr << 8) | (ch & 0xFF));
    js_pushundefined(J);
}

/* hideCursor() / showCursor() — disable/enable the blinking hardware cursor */
static void js_fn_hidecursor(js_State *J) {
    vga_cursor_disable();
    js_pushundefined(J);
}
static void js_fn_showcursor(js_State *J) {
    vga_cursor_enable(14, 15);
    js_pushundefined(J);
}

/* ── Process list binding ─────────────────────────────────────────────────── */

/* getProcessList() → array of {pid, name, state, ring, priority} objects */
static void js_fn_getprocesslist(js_State *J) {
    static proc_snap_t snaps[MAX_PROCS];
    int count = proc_snapshot(snaps, MAX_PROCS);
    js_newarray(J);
    for (int i = 0; i < count; i++) {
        js_newobject(J);
        js_pushnumber(J, (double)snaps[i].pid);      js_setproperty(J, -2, "pid");
        js_pushstring(J, snaps[i].name);             js_setproperty(J, -2, "name");
        js_pushnumber(J, (double)snaps[i].state);    js_setproperty(J, -2, "state");
        js_pushnumber(J, (double)snaps[i].ring);     js_setproperty(J, -2, "ring");
        js_pushnumber(J, (double)snaps[i].priority); js_setproperty(J, -2, "priority");
        js_setindex(J, -2, i);
    }
}

/* ── Error reporter ───────────────────────────────────────────────────────── */
static void js_report_fn(js_State *J, const char *msg) {
    (void)J;
    kprint("[JS] ");
    kprint(msg);
    kprint("\n");
}

/* ── Public API ───────────────────────────────────────────────────────────── */
void js_runtime_run(const char *source) {
    js_State *J = js_newstate(NULL, NULL, JS_STRICT);
    if (!J) { kprint("[JS] failed to create state\n"); return; }

    js_setreport(J, js_report_fn);

    /* I/O */
    js_newcfunction(J, js_fn_print,       "print",       1); js_setglobal(J, "print");
    js_newcfunction(J, js_fn_println,     "println",     1); js_setglobal(J, "println");
    js_newcfunction(J, js_fn_readline,    "readline",    0); js_setglobal(J, "readline");
    js_newcfunction(J, js_fn_getchar,          "getChar",        0); js_setglobal(J, "getChar");
    js_newcfunction(J, js_fn_getkey_nonblock,  "getKeyNonBlock", 0); js_setglobal(J, "getKeyNonBlock");
    js_newcfunction(J, js_fn_getticks,         "getTicks",       0); js_setglobal(J, "getTicks");
    js_newcfunction(J, js_fn_getgametick,      "getGameTick",    0); js_setglobal(J, "getGameTick");

    /* Terminal control */
    js_newcfunction(J, js_fn_setcursor,   "setCursor",   2); js_setglobal(J, "setCursor");
    js_newcfunction(J, js_fn_setcolor,    "setColor",    2); js_setglobal(J, "setColor");
    js_newcfunction(J, js_fn_screenwidth, "screenWidth",  0); js_setglobal(J, "screenWidth");
    js_newcfunction(J, js_fn_screenheight,"screenHeight", 0); js_setglobal(J, "screenHeight");
    js_newcfunction(J, js_fn_clearscreen, "clearScreen",  0); js_setglobal(J, "clearScreen");
    js_newcfunction(J, js_fn_printat,     "printAt",     3); js_setglobal(J, "printAt");
    js_newcfunction(J, js_fn_vgapoke,    "vgaPoke",     4); js_setglobal(J, "vgaPoke");
    js_newcfunction(J, js_fn_hidecursor, "hideCursor",  0); js_setglobal(J, "hideCursor");
    js_newcfunction(J, js_fn_showcursor, "showCursor",  0); js_setglobal(J, "showCursor");

    /* CWD */
    js_newcfunction(J, js_fn_chdir,  "chdir",  1); js_setglobal(J, "chdir");
    js_newcfunction(J, js_fn_getcwd, "getcwd", 0); js_setglobal(J, "getcwd");

    /* Process info */
    js_newcfunction(J, js_fn_getprocesslist, "getProcessList", 0); js_setglobal(J, "getProcessList");

    /* Filesystem */
    js_newcfunction(J, js_fn_open,    "fsOpen",    2); js_setglobal(J, "fsOpen");
    js_newcfunction(J, js_fn_close,   "fsClose",   1); js_setglobal(J, "fsClose");
    js_newcfunction(J, js_fn_read,    "fsRead",    2); js_setglobal(J, "fsRead");
    js_newcfunction(J, js_fn_write,   "fsWrite",   2); js_setglobal(J, "fsWrite");
    js_newcfunction(J, js_fn_readdir, "fsReaddir", 2); js_setglobal(J, "fsReaddir");
    js_newcfunction(J, js_fn_stat,    "fsStat",    1); js_setglobal(J, "fsStat");
    js_newcfunction(J, js_fn_mkdir,   "fsMkdir",   1); js_setglobal(J, "fsMkdir");
    js_newcfunction(J, js_fn_unlink,  "fsUnlink",  1); js_setglobal(J, "fsUnlink");
    js_newcfunction(J, js_fn_creat,   "fsCreat",   1); js_setglobal(J, "fsCreat");

    /* Inject signal library into every state before the app runs */
    if (js_dostring(J, js_signal_prelude)) {
        kprint("[JS] signal prelude failed\n");
    }

    if (js_dostring(J, source)) {
        /* error already reported via js_report_fn */
    }

    js_freestate(J);
}

#ifndef _VGA_H
#define _VGA_H

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>

/* ── Text mode geometry ───────────────────────────────────────────────────── */
#define VGA_WIDTH   80
#define VGA_HEIGHT  25
#define VGA_ADDR    ((volatile uint16_t *)0xB8000)

/* ── VGA I/O ports (used only in VGA text-mode path) ─────────────────────── */
#define VGA_MISC_WRITE      0x3C2
#define VGA_MISC_READ       0x3CC
#define VGA_SEQ_INDEX       0x3C4
#define VGA_SEQ_DATA        0x3C5
#define VGA_GC_INDEX        0x3CE
#define VGA_GC_DATA         0x3CF
#define VGA_CRTC_INDEX      0x3D4
#define VGA_CRTC_DATA       0x3D5
#define VGA_AC_INDEX        0x3C0
#define VGA_AC_WRITE        0x3C0
#define VGA_AC_READ         0x3C1
#define VGA_INSTAT_READ     0x3DA

/* ── Colour attributes (VGA text-mode palette) ────────────────────────────── */
#define VGA_COLOR(fg, bg)   ((uint8_t)(((bg) << 4) | ((fg) & 0x0F)))

typedef enum {
    VGA_BLACK=0, VGA_BLUE, VGA_GREEN, VGA_CYAN,
    VGA_RED, VGA_MAGENTA, VGA_BROWN, VGA_LIGHT_GREY,
    VGA_DARK_GREY, VGA_LIGHT_BLUE, VGA_LIGHT_GREEN, VGA_LIGHT_CYAN,
    VGA_LIGHT_RED, VGA_LIGHT_MAGENTA, VGA_LIGHT_BROWN, VGA_WHITE,
} vga_color_t;

/* ── State (character-grid logical cursor) ────────────────────────────────── */
extern size_t  vga_col;
extern size_t  vga_row;
extern uint8_t vga_color;   /* current fg/bg attribute byte (VGA text palette) */

/* ── Helpers ──────────────────────────────────────────────────────────────── */
static inline uint16_t vga_entry(char c, uint8_t color) {
    return (uint16_t)(uint8_t)c | ((uint16_t)color << 8);
}

/* ── Initialisation ───────────────────────────────────────────────────────── */

/* BIOS / Multiboot 1 path: hardware VGA text mode (I/O port access) */
void vga_init(void);

/* GOP / Multiboot 2 path: software framebuffer renderer — no I/O ports */
void vga_init_gop(void);

/* ── Screen control ───────────────────────────────────────────────────────── */
void vga_clear(void);

/* (VGA text-mode only) hardware cursor */
void vga_cursor_move(size_t col, size_t row);
void vga_cursor_enable(uint8_t cursor_start, uint8_t cursor_end);
void vga_cursor_disable(void);

/* Move logical cursor without printing */
void vga_goto(size_t col, size_t row);

/* ── Print functions (work on both paths) ─────────────────────────────────── */
void kprint_char(char c);
void kprint(const char *str);
void kprint_color(const char *str, uint8_t color);
void kprint_uint64(uint64_t n);
void kprint_hex(uint64_t n);

#endif /* _VGA_H */

