        vgaPoke(col, row, ch.charCodeAt(0), attr(fg, bg));
    }

    function pokeStr(col, row, s, fg, bg) {
        for (var i = 0; i < s.length && col + i < W; i++)
            vgaPoke(col + i, row, s.charCodeAt(i), attr(fg, bg));
    }

    function hline(col, row, width, fg, bg) {
        for (var i = 0; i < width; i++)
            vgaPoke(col + i, row, 0x20, attr(fg, bg));
    }

    /* pad/truncate string to exact width */
    function fit(s, w) {
        s = String(s);
        while (s.length < w) s = s + " ";
        if (s.length > w) s = s.substr(0, w);
        return s;
    }

    function rjust(s, w) {
        s = String(s);
        while (s.length < w) s = " " + s;
        return s;
    }

    /* ── Bar renderer ─────────────────────────────────────────────────────── */
    /* Renders: [####      ] where filled chars are LGREEN on BLACK */
    function drawBar(col, row, barW, used, total, fillFg, emptyFg) {
        var filled = (total > 0) ? Math.floor((used / total) * barW) : 0;
        if (filled > barW) filled = barW;
        poke(col, row, "[", LGREY, BLACK);
        for (var i = 0; i < barW; i++) {
            if (i < filled)
                vgaPoke(col + 1 + i, row, 0x7C /* | */, attr(fillFg, BLACK));
            else
                vgaPoke(col + 1 + i, row, 0x20, attr(emptyFg, BLACK));
        }
        poke(col + 1 + barW, row, "]", LGREY, BLACK);
    }

    /* ── State labels ─────────────────────────────────────────────────────── */
    var STATE_NAME = ["unused", "embryo", "ready", "running", "blocked", "zombie"];
    var RING_NAME  = ["kernel", "service"];

    /* ── Scroll state ─────────────────────────────────────────────────────── */
    var scrollTop = 0;
    var PROC_ROWS = 16;   /* rows available for the process list */

    /* ── Render ───────────────────────────────────────────────────────────── */
    function render() {
        var mem  = getMemInfo();
        var up   = getUptime();
        var proc = getProcessList();

        /* row 0 — title bar */
        hline(0, 0, W, BLACK, LGREEN);
        var title = " NephilimOS htop  [q=quit  UP/DOWN=scroll]";
        pokeStr(0, 0, title, BLACK, LGREEN);
        var uptimeStr = "up " + rjust(String(up), 6) + "s ";
        pokeStr(W - uptimeStr.length, 0, uptimeStr, BLACK, LGREEN);

        /* row 1 — CPU placeholder (tick-based, no per-proc accounting yet) */
        var ticksNow = getTicks();
        pokeStr(0, 1, "  CPU", LGREEN, BLACK);
        pokeStr(5, 1, " [", LGREY, BLACK);
        var cpuBarW = W - 18;
        /* We cannot measure CPU% without two samples; show ticks modulo bar */
        var tickFill = ticksNow % (cpuBarW + 1);
        for (var i = 0; i < cpuBarW; i++) {
            var ch = (i < tickFill) ? 0x7C : 0x20;
            var fg = (i < tickFill) ? LGREEN : DGREY;
            vgaPoke(7 + i, 1, ch, attr(fg, BLACK));
        }
        pokeStr(7 + cpuBarW, 1, "]", LGREY, BLACK);
        var pcStr = rjust(String(tickFill), 3) + "%";
        pokeStr(9 + cpuBarW, 1, pcStr, WHITE, BLACK);

        /* row 2 — MEM bar */
        var memUsedMB  = Math.floor(mem.usedKB  / 1024);
        var memTotalMB = Math.floor(mem.totalKB / 1024);
        pokeStr(0, 2, "  Mem", LGREEN, BLACK);
        var memBarW = W - 18;
        drawBar(5, 2, memBarW, mem.usedKB, mem.totalKB, LGREEN, DGREY);
        var memStr = rjust(String(memUsedMB), 4) + "/" + fit(String(memTotalMB), 4) + "MB";
        pokeStr(8 + memBarW, 2, memStr, WHITE, BLACK);

        /* row 3 — separator */
        hline(0, 3, W, DGREY, BLACK);
        pokeStr(0, 3, "  PID", LGREEN, BLACK);
        pokeStr(6, 3,  fit("NAME",    16), LGREEN, BLACK);
        pokeStr(23, 3, fit("RING",    7),  LGREEN, BLACK);
        pokeStr(31, 3, fit("STATE",   9),  LGREEN, BLACK);
        pokeStr(41, 3, fit("PRI",     4),  LGREEN, BLACK);

        /* rows 4..4+PROC_ROWS-1 — process list */
        var visCount = (proc.length - scrollTop);
        if (visCount > PROC_ROWS) visCount = PROC_ROWS;

        for (var r = 0; r < PROC_ROWS; r++) {
            var row = 4 + r;
            var idx = scrollTop + r;
            if (idx >= proc.length) {
                hline(0, row, W, BLACK, BLACK);
                continue;
            }
            var p = proc[idx];
            var isRunning = (p.state === 3);
            var rowFg = isRunning ? LGREEN : WHITE;
            var rowBg = BLACK;

            hline(0, row, W, rowFg, rowBg);
            pokeStr(0,  row, rjust(String(p.pid), 5),               rowFg, rowBg);
            pokeStr(6,  row, fit(p.name, 16),                        rowFg, rowBg);
            var ringStr  = (p.ring  < RING_NAME.length)  ? RING_NAME[p.ring]   : "?";
            var stateStr = (p.state < STATE_NAME.length) ? STATE_NAME[p.state] : "?";
            pokeStr(23, row, fit(ringStr,  7),  CYAN,  rowBg);
            pokeStr(31, row, fit(stateStr, 9),  isRunning ? LGREEN : YELLOW, rowBg);
            pokeStr(41, row, fit(String(p.priority), 4), LGREY, rowBg);
        }

        /* row 4+PROC_ROWS — scroll indicator */
        var scrollRow = 4 + PROC_ROWS;
        hline(0, scrollRow, W, DGREY, BLACK);
        var total = proc.length;
        var end   = scrollTop + visCount;
        var scrollMsg = "  Showing " + (scrollTop+1) + "-" + end + " of " + total + " processes";
        pokeStr(0, scrollRow, scrollMsg, LGREY, BLACK);

        /* bottom status bar */
        hline(0, H-1, W, BLACK, BLUE);
        pokeStr(0, H-1, "  F5/r:refresh  q:quit  UP/DOWN:scroll", WHITE, BLUE);
    }

    /* ── Key constants ────────────────────────────────────────────────────── */
    var KEY_Q     = 113;  /* 'q' */
    var KEY_UP    = 0x148;
    var KEY_DOWN  = 0x150;
    var KEY_R     = 114;  /* 'r' */
    var KEY_F5    = 0x13F;

    /* ── Main loop ────────────────────────────────────────────────────────── */
    hideCursor();
    clearScreen();
    render();

    var lastTick = getTicks();
    var REFRESH_TICKS = 100; /* ~1 s at 100 Hz PIT */

    var running = true;
    while (running) {
        var k = getKeyNonBlock();
        if (k !== -1) {
            if (k === KEY_Q) {
                running = false;
            } else if (k === KEY_DOWN) {
                var procs = getProcessList();
                if (scrollTop + PROC_ROWS < procs.length) scrollTop++;
                render();
            } else if (k === KEY_UP) {
                if (scrollTop > 0) scrollTop--;
                render();
            } else if (k === KEY_R || k === KEY_F5) {
                render();
            }
        }

        var now = getTicks();
        if (now - lastTick >= REFRESH_TICKS) {
            lastTick = now;
            render();
        }
    }

    showCursor();
    clearScreen();
})();

content.content:
1	/*
2	 * Snake — dual-renderer:
3	 *   GOP (MB2/UEFI): full pixel rendering, large board, colored rectangles.
4	 *   VGA (MB1/BIOS): ASCII character grid, 80×25 text mode.
5	 *
6	 * Controls: WASD / arrow keys. P = pause. Q = quit.
7	 * Highscore: /tmp/snake_hi
8	 */
9	#include <syscall.h>
10	#include <keyboard.h>
11	#include <timer.h>
12	#include <fs.h>
13	#include <stdint.h>
14	#include <stddef.h>
15	
16	/* ────────────────────────────────────────────────────────────────────────────
17	 * Highscore helpers
18	 * ──────────────────────────────────────────────────────────────────────────*/
19	#define HISCORE_PATH "/tmp/snake_hi"
20	
21	static int hs_atoi(const char *s) {
22	    int n = 0;
23	    while (*s >= '0' && *s <= '9') n = n * 10 + (*s++ - '0');
24	    return n;
25	}
26	static int hs_load(void) {
27	    int64_t fd = syscall3(SYS_FS_OPEN, (uint64_t)HISCORE_PATH, O_RDONLY, 0);
28	    if (fd < 0) return 0;
29	    char buf[16] = {0};
30	    syscall3(SYS_FS_READ, (uint64_t)fd, (uint64_t)buf, sizeof(buf)-1);
31	    syscall1(SYS_FS_CLOSE, (uint64_t)fd);
32	    return hs_atoi(buf);
33	}
34	static void hs_save(int hi) {
35	    char buf[12]; int i = 0;
36	    if (!hi) { buf[i++] = '0'; }
37	    else {
38	        char tmp[12]; int t = 0, n = hi;
39	        while (n) { tmp[t++] = '0' + n%10; n /= 10; }
40	        while (t)  buf[i++] = tmp[--t];
41	    }
42	    buf[i] = '\0';
43	    int64_t fd = syscall3(SYS_FS_OPEN, (uint64_t)HISCORE_PATH,
44	                          O_WRONLY|O_CREAT|O_TRUNC, 0644);
45	    if (fd < 0) return;
46	    syscall3(SYS_FS_WRITE, (uint64_t)fd, (uint64_t)buf, (uint64_t)i);
47	    syscall1(SYS_FS_CLOSE, (uint64_t)fd);
48	}
49	
50	/* ────────────────────────────────────────────────────────────────────────────
51	 * Shared: VGA colour palette (text mode attributes + GOP RGB lookup)
52	 * ──────────────────────────────────────────────────────────────────────────*/
53	#define C_BLACK    0
54	#define C_BLUE     1
55	#define C_GREEN    2
56	#define C_CYAN     3
57	#define C_RED      4
58	#define C_MAGENTA  5
59	#define C_BROWN    6
60	#define C_LGREY    7
61	#define C_DGREY    8
62	#define C_LBLUE    9
63	#define C_LGREEN  10
64	#define C_LCYAN   11
65	#define C_LRED    12
66	#define C_LMAGENTA 13
67	#define C_YELLOW  14
68	#define C_WHITE   15
69	
70	#define COL(fg,bg) ((uint8_t)(((bg)<<4)|((fg)&0x0F)))
71	
72	/* ────────────────────────────────────────────────────────────────────────────
73	 * RNG
74	 * ──────────────────────────────────────────────────────────────────────────*/
75	static uint32_t rng_state = 12345;
76	static uint32_t rng_next(void) {
77	    rng_state = rng_state * 1664525u + 1013904223u;
78	    return rng_state;
79	}
80	
81	/* ────────────────────────────────────────────────────────────────────────────
82	 * String helpers (no libc)
83	 * ──────────────────────────────────────────────────────────────────────────*/
84	static void itoa_s(int n, char *buf) {
85	    if (!n) { buf[0]='0'; buf[1]='\0'; return; }
86	    char tmp[12]; int i=0, j=0;
87	    while (n) { tmp[i++]='0'+n%10; n/=10; }
88	    while (i)  buf[j++]=tmp[--i];
89	    buf[j]='\0';
90	}
91	static int strlen_s(const char *s) { int n=0; while(*s++) n++; return n; }
92	
93	/* ────────────────────────────────────────────────────────────────────────────
94	 * Direction
95	 * ──────────────────────────────────────────────────────────────────────────*/
96	#define DIR_UP    0
97	#define DIR_DOWN  1
98	#define DIR_LEFT  2
99	#define DIR_RIGHT 3
100	
101	/* ════════════════════════════════════════════════════════════════════════════
102	 *  VGA TEXT-MODE RENDERER  (MB1 / BIOS path)
103	 * ════════════════════════════════════════════════════════════════════════════*/
104	
105	#define VGA_BOARD_X  1
106	#define VGA_BOARD_Y  2
107	#define VGA_BOARD_W 50
108	#define VGA_BOARD_H 20
109	#define VGA_MAX_LEN (VGA_BOARD_W * VGA_BOARD_H)
110	
111	static int  vsx[VGA_MAX_LEN], vsy[VGA_MAX_LEN];
112	static int  vslen, vdx, vdy, vax, vay, vscore, vbest, vpaused, vdead, vdir;
113	
114	static void vga_put(int col, int row, char ch, uint8_t attr) {
115	    uint64_t packed = (uint64_t)(uint8_t)ch | ((uint64_t)attr << 8);
116	    syscall3(SYS_PUTCELL, (uint64_t)col, (uint64_t)row, packed);
117	}
118	static void vga_str(int col, int row, const char *s, uint8_t attr) {
119	    while (*s) vga_put(col++, row, *s++, attr);
120	}
121	static void vga_draw_cell(int x, int y, char ch, uint8_t attr) {
122	    vga_put(VGA_BOARD_X+x, VGA_BOARD_Y+y, ch, attr);
123	}
124	static void vga_erase_cell(int x, int y) {
125	    vga_draw_cell(x, y, ' ', COL(C_LGREY, C_BLACK));
126	}
127	static void vga_draw_border(void) {
128	    uint8_t ba = COL(C_LGREY, C_BLACK);
129	    for (int x=0; x<VGA_BOARD_W+2; x++) {
130	        vga_put(VGA_BOARD_X-1+x, VGA_BOARD_Y-1,         '-', ba);
131	        vga_put(VGA_BOARD_X-1+x, VGA_BOARD_Y+VGA_BOARD_H, '-', ba);
132	    }
133	    for (int y=0; y<VGA_BOARD_H; y++) {
134	        vga_put(VGA_BOARD_X-1,         VGA_BOARD_Y+y, '|', ba);
135	        vga_put(VGA_BOARD_X+VGA_BOARD_W, VGA_BOARD_Y+y, '|', ba);
136	    }
137	}
138	static void vga_draw_hud(void) {
139	    uint8_t ha = COL(C_WHITE, C_BLACK);
140	    int hx = VGA_BOARD_X + VGA_BOARD_W + 3;
141	    char buf[12];
142	    vga_str(hx, VGA_BOARD_Y,   "SNAKE",   COL(C_LBLUE, C_BLACK));
143	    vga_str(hx, VGA_BOARD_Y+2, "Score:",  ha);
144	    vga_str(hx+7, VGA_BOARD_Y+2, "      ", ha);
145	    itoa_s(vscore, buf); vga_str(hx+7, VGA_BOARD_Y+2, buf, COL(C_YELLOW,C_BLACK));
146	    vga_str(hx, VGA_BOARD_Y+3, "Best: ",  ha);
147	    vga_str(hx+7, VGA_BOARD_Y+3, "      ", ha);
148	    itoa_s(vbest, buf);  vga_str(hx+7, VGA_BOARD_Y+3, buf, COL(C_LGREEN,C_BLACK));
149	    vga_str(hx, VGA_BOARD_Y+5, "WASD/",   ha);
150	    vga_str(hx, VGA_BOARD_Y+6, "arrows",  ha);
151	    vga_str(hx, VGA_BOARD_Y+7, "P pause", ha);
152	    vga_str(hx, VGA_BOARD_Y+8, "Q quit",  ha);
153	}
154	static void vga_place_apple(void) {
155	    for (int a=0; a<1000; a++) {
156	        int nx=(int)(rng_next()%(uint32_t)VGA_BOARD_W);
157	        int ny=(int)(rng_next()%(uint32_t)VGA_BOARD_H);
158	        int ok=1;
159	        for (int i=0;i<vslen;i++) if(vsx[i]==nx&&vsy[i]==ny){ok=0;break;}
160	        if (ok){vax=nx;vay=ny;return;}
161	    }
162	}
163	static void vga_draw_snake(void) {
164	    vga_draw_cell(vsx[0],vsy[0],'@',COL(C_LBLUE,C_BLACK));
165	    for(int i=1;i<vslen;i++) vga_draw_cell(vsx[i],vsy[i],'o',COL(C_BLUE,C_BLACK));
166	}
167	static void vga_game_init(void) {
168	    rng_state ^= (uint32_t)timer_ticks;
169	    vslen=3; vdx=1; vdy=0; vdir=DIR_RIGHT;
170	    vscore=0; vpaused=0; vdead=0;
171	    int hx=VGA_BOARD_W/2, hy=VGA_BOARD_H/2;
172	    for(int i=0;i<vslen;i++){vsx[i]=hx-i;vsy[i]=hy;}
173	    vga_place_apple();
174	}
175	static void vga_step(void) {
176	    int nx=vsx[0]+vdx, ny=vsy[0]+vdy;
177	    if(nx<0||nx>=VGA_BOARD_W||ny<0||ny>=VGA_BOARD_H){vdead=1;return;}
178	    for(int i=0;i<vslen;i++) if(vsx[i]==nx&&vsy[i]==ny){vdead=1;return;}
179	    int ate=(nx==vax&&ny==vay);
180	    if(!ate) vga_erase_cell(vsx[vslen-1],vsy[vslen-1]);
181	    int nl=ate?vslen+1:vslen; if(nl>VGA_MAX_LEN)nl=VGA_MAX_LEN;
182	    for(int i=nl-1;i>0;i--){vsx[i]=vsx[i-1];vsy[i]=vsy[i-1];}
183	    vsx[0]=nx;vsy[0]=ny;vslen=nl;
184	    if(ate){vscore++;vga_draw_hud();vga_place_apple();
185	        vga_draw_cell(vax,vay,'*',COL(C_LMAGENTA,C_BLACK));}
186	    vga_draw_snake();
187	}
188	
189	static void snake_vga(void) {
190	    vbest=hs_load();
191	    syscall0(SYS_CLEAR);
192	    vga_draw_border();
193	    vga_game_init();
194	    vga_draw_hud();
195	    vga_draw_cell(vax,vay,'*',COL(C_LMAGENTA,C_BLACK));
196	    vga_draw_snake();
197	    uint32_t last=(uint32_t)timer_ticks;
198	    for(;;){
199	        int k=(int)syscall0(SYS_GETKEY_NB);
200	        if(k>=0){
201	            if(k=='q'||k=='Q'){vdead=1;}
202	            else if(k=='p'||k=='P'){vpaused^=1;}
203	            else {
204	                int nd=vdir;
205	                if((k=='w'||k=='W'||k==KEY_UP)   &&vdir!=DIR_DOWN) nd=DIR_UP;
206	                if((k=='s'||k=='S'||k==KEY_DOWN)  &&vdir!=DIR_UP)   nd=DIR_DOWN;
207	                if((k=='a'||k=='A'||k==KEY_LEFT)  &&vdir!=DIR_RIGHT)nd=DIR_LEFT;
208	                if((k=='d'||k=='D'||k==KEY_RIGHT) &&vdir!=DIR_LEFT) nd=DIR_RIGHT;
209	                if(nd!=vdir){vdir=nd;
210	                    if(vdir==DIR_UP){vdx=0;vdy=-1;}
211	                    else if(vdir==DIR_DOWN){vdx=0;vdy=1;}
212	                    else if(vdir==DIR_LEFT){vdx=-1;vdy=0;}
213	                    else{vdx=1;vdy=0;}
214	                }
215	            }
216	        }
217	        if(vdead) break;
218	        if(!vpaused){
219	            uint32_t sp=12;
220	            if(vscore>=10)sp=9; if(vscore>=20)sp=7; if(vscore>=35)sp=5;
221	            uint32_t now=(uint32_t)timer_ticks;
222	            if((uint32_t)(now-last)>=sp){last=now;vga_step();if(vdead)break;}
223	        }
224	        syscall0(SYS_YIELD);
225	    }
226	    int nb=(vscore>vbest); if(nb){vbest=vscore;hs_save(vbest);}
227	    int cx=VGA_BOARD_X+VGA_BOARD_W/2, cy=VGA_BOARD_Y+VGA_BOARD_H/2-1;
228	    vga_str(cx-4,cy,"GAME OVER",COL(C_LRED,C_BLACK));
229	    char buf[12]; itoa_s(vscore,buf);
230	    vga_str(cx-5,cy+1,"Score: ",COL(C_WHITE,C_BLACK));
231	    vga_str(cx+2, cy+1,buf,COL(C_YELLOW,C_BLACK));
232	    if(nb) vga_str(cx-5,cy+2,"New best!",COL(C_LGREEN,C_BLACK));
233	    else { char bb[12]; itoa_s(vbest,bb);
234	        vga_str(cx-5,cy+2,"Best: ",COL(C_WHITE,C_BLACK));
235	        vga_str(cx+1,cy+2,bb,COL(C_LGREEN,C_BLACK));}
236	    vga_str(cx-8,cy+3,"Press any key...",COL(C_LGREY,C_BLACK));
237	    syscall0(SYS_GETKEY);
238	    syscall0(SYS_CLEAR);
239	}
240	
241	/* ════════════════════════════════════════════════════════════════════════════
242	 *  GOP PIXEL RENDERER  (MB2 / UEFI path)
243	 * ════════════════════════════════════════════════════════════════════════════
244	 *
245	 * Layout at 1280×800:
246	 *   Cell size: 20×20 px
247	 *   Board: 54 cols × 36 rows = 1080×720 px
248	 *   Board origin: x=20, y=40 (leaves room for title bar + right sidebar)
249	 *   Sidebar: x=1120, width=140 px
250	 *   Border: 4 px thick filled rect around the board
251	 */
252	
253	/* packed 0x00RRGGBB → syscall arg */
254	#define RGB(r,g,b) ((uint32_t)(((uint32_t)(r)<<16)|((uint32_t)(g)<<8)|(uint32_t)(b)))
255	
256	/* ── Colour schemes ──────────────────────────────────────────────────────────
257	 * Scheme 0: Green snake / Red fruit  (classic)
258	 * Scheme 1: Blue snake  / Purple fruit
259	 * ──────────────────────────────────────────────────────────────────────────*/
260	#define NUM_SCHEMES 2
261	static int g_scheme = 0;
262	
263	typedef struct {
264	    uint32_t bg;
265	    uint32_t border;
266	    uint32_t grid;
267	    uint32_t head;
268	    uint32_t body;
269	    uint32_t fruit;
270	    uint32_t sidebar;
271	    uint8_t  title_attr;
272	    uint8_t  score_attr;
273	    uint8_t  best_attr;
274	} color_scheme_t;
275	
276	static const color_scheme_t schemes[NUM_SCHEMES] = {
277	    /* 0 — Green / Red */
278	    {
279	        .bg       = RGB(0x0D,0x0D,0x1A),
280	        .border   = RGB(0x33,0x55,0x33),
281	        .grid     = RGB(0x14,0x1E,0x14),
282	        .head     = RGB(0x00,0xFF,0x88),
283	        .body     = RGB(0x00,0xCC,0x44),
284	        .fruit    = RGB(0xFF,0x22,0x33),
285	        .sidebar  = RGB(0x0A,0x14,0x0A),
286	        .title_attr  = COL(C_LGREEN, C_BLACK),
287	        .score_attr  = COL(C_YELLOW, C_BLACK),
288	        .best_attr   = COL(C_LGREEN, C_BLACK),
289	    },
290	    /* 1 — Blue / Purple */
291	    {
292	        .bg       = RGB(0x08,0x08,0x18),
293	        .border   = RGB(0x33,0x33,0x77),
294	        .grid     = RGB(0x10,0x10,0x22),
295	        .head     = RGB(0x44,0xAA,0xFF),
296	        .body     = RGB(0x22,0x66,0xCC),
297	        .fruit    = RGB(0xCC,0x44,0xFF),
298	        .sidebar  = RGB(0x08,0x08,0x20),
299	        .title_attr  = COL(C_LCYAN,  C_BLACK),
300	        .score_attr  = COL(C_LBLUE,  C_BLACK),
301	        .best_attr   = COL(C_LMAGENTA, C_BLACK),
302	    },
303	};
304	
305	/* Convenience accessor */
306	#define S (schemes[g_scheme])
307	
308	#define COL_CELL_EMPTY (S.bg)
309	
310	/* Board geometry — computed from framebuffer; stored at init */
311	static uint32_t G_cell;          /* cell size in pixels          */
312	static uint32_t G_bx, G_by;     /* board pixel origin           */
313	static uint32_t G_bw, G_bh;     /* board pixel size             */
314	static int      G_cols, G_rows;  /* board dimensions in cells    */
315	static uint32_t G_sbx;           /* sidebar x                    */
316	static uint32_t G_fbw, G_fbh;   /* framebuffer pixel dimensions */
317	
318	#define GOP_MAX_LEN (128*128)
319	static int gsx[GOP_MAX_LEN], gsy[GOP_MAX_LEN];
320	static int gslen, gdx, gdy, gax, gay, gscore, gbest, gpaused, gdead, gdir;
321	
322	/* ── Low-level fill rectangle via syscall ─────────────────────────────────── */
323	static void fill(uint32_t x, uint32_t y, uint32_t w, uint32_t h, uint32_t c) {
324	    syscall5(SYS_FB_FILLRECT, x, y, w, h, (uint64_t)c);
325	}
326	
327	/* ── Draw a single game cell ──────────────────────────────────────────────── */
328	static void gop_draw_cell(int cx, int cy, uint32_t color) {
329	    uint32_t px = G_bx + (uint32_t)cx * G_cell + 1;
330	    uint32_t py = G_by + (uint32_t)cy * G_cell + 1;
331	    fill(px, py, G_cell-2, G_cell-2, color);
332	}
333	
334	static void gop_erase_cell(int cx, int cy) {
335	    gop_draw_cell(cx, cy, COL_CELL_EMPTY);
336	}
337	
338	/* ── Draw the grid lines ──────────────────────────────────────────────────── */
339	static void gop_draw_grid(void) {
340	    for (int r=0; r<=G_rows; r++)
341	        fill(G_bx, G_by+(uint32_t)r*G_cell, G_bw, 1, S.grid);
342	    for (int c=0; c<=G_cols; c++)
343	        fill(G_bx+(uint32_t)c*G_cell, G_by, 1, G_bh, S.grid);
344	}
345	
346	/* ── Inline bitmap font renderer via SYS_PUTCELL ─────────────────────────── */
347	/* We re-use the kernel's char renderer for sidebar text — it's already routed
348	   through GOP. We compute the char column/row from pixel coords. */
349	static void gop_text(uint32_t px, uint32_t py, const char *s, uint8_t attr) {
350	    uint32_t col = px / 8;
351	    uint32_t row = py / 16;
352	    while (*s) {
353	        uint64_t packed = (uint64_t)(uint8_t)*s | ((uint64_t)attr << 8);
354	        syscall3(SYS_PUTCELL, (uint64_t)col++, (uint64_t)row, packed);
355	        s++;
356	    }
357	}
358	
359	/* Convenience: print integer at pixel position */
360	static void gop_text_int(uint32_t px, uint32_t py, int n, uint8_t attr) {
361	    char buf[12]; itoa_s(n, buf); gop_text(px, py, buf, attr);
362	}
363	
364	/* ── Sidebar layout constants (pixel rows) ────────────────────────────────── */
365	#define SB_TITLE_Y   32
366	#define SB_SCR_LBL_Y 96
367	#define SB_SCR_VAL_Y 116
368	#define SB_BST_LBL_Y 156
369	#define SB_BST_VAL_Y 176
370	#define SB_CTL_Y     240
371	#define SB_DOT_Y     380
372	
373	/* ── Sidebar ──────────────────────────────────────────────────────────────── */
374	static void gop_draw_sidebar(void) {
375	    fill(G_sbx, 0, G_fbw - G_sbx, G_fbh, S.sidebar);
376	
377	    uint32_t tx = G_sbx + 12;
378	    gop_text(tx, SB_TITLE_Y,   "SNAKE",        S.title_attr);
379	
380	    gop_text(tx, SB_SCR_LBL_Y, "Score",        COL(C_WHITE,  C_BLACK));
381	    gop_text_int(tx, SB_SCR_VAL_Y, gscore,     S.score_attr);
382	
383	    gop_text(tx, SB_BST_LBL_Y, "Best",         COL(C_WHITE,  C_BLACK));
384	    gop_text_int(tx, SB_BST_VAL_Y, gbest,      S.best_attr);
385	
386	    gop_text(tx, SB_CTL_Y,       "Controls:",  COL(C_LGREY, C_BLACK));
387	    gop_text(tx, SB_CTL_Y + 24,  "WASD/arrows",COL(C_LGREY, C_BLACK));
388	    gop_text(tx, SB_CTL_Y + 44,  "P  pause",   COL(C_LGREY, C_BLACK));
389	    gop_text(tx, SB_CTL_Y + 64,  "Q  quit",    COL(C_LGREY, C_BLACK));
390	    gop_text(tx, SB_CTL_Y + 84,  "C  colors",  COL(C_LGREY, C_BLACK));
391	
392	    /* Scheme indicator */
393	    fill(G_sbx + 12, SB_DOT_Y, 12, 12, S.head);
394	    gop_text(tx + 18, SB_DOT_Y,
395	             g_scheme == 0 ? "Green/Red" : "Blue/Purp",
396	             COL(C_LGREY, C_BLACK));
397	}
398	
399	static void gop_update_score(void) {
400	    uint32_t tx = G_sbx + 12;
401	    fill(tx, SB_SCR_VAL_Y, 96, 16, S.sidebar);
402	    fill(tx, SB_BST_VAL_Y, 96, 16, S.sidebar);
403	    gop_text_int(tx, SB_SCR_VAL_Y, gscore, S.score_attr);
404	    gop_text_int(tx, SB_BST_VAL_Y, gbest,  S.best_attr);
405	}
406	
407	/* ── Full screen repaint (called on scheme switch) ────────────────────────── */
408	static void gop_repaint_all(void);
409	
410	/* ── Title bar ────────────────────────────────────────────────────────────── */
411	static void gop_draw_title(void) {
412	    fill(0, 0, G_sbx, G_by, S.bg);
413	    gop_text(G_bx, 12, "NephilimOS  Snake", S.title_attr);
414	}
415	
416	/* ── Border around board ──────────────────────────────────────────────────── */
417	static void gop_draw_border(void) {
418	    uint32_t t = 3;
419	    fill(G_bx-t, G_by-t, G_bw+2*t, t,      S.border);
420	    fill(G_bx-t, G_by+G_bh, G_bw+2*t, t,   S.border);
421	    fill(G_bx-t, G_by-t, t,      G_bh+2*t, S.border);
422	    fill(G_bx+G_bw, G_by-t, t,   G_bh+2*t, S.border);
423	}
424	
425	/* ── Apple ────────────────────────────────────────────────────────────────── */
426	static void gop_place_apple(void) {
427	    int max = G_cols * G_rows;
428	    for (int a=0; a<1000; a++) {
429	        int nx=(int)(rng_next()%(uint32_t)G_cols);
430	        int ny=(int)(rng_next()%(uint32_t)G_rows);
431	        int ok=1;
432	        for(int i=0;i<gslen;i++) if(gsx[i]==nx&&gsy[i]==ny){ok=0;break;}
433	        if(ok){gax=nx;gay=ny;return;}
434	        (void)max;
435	    }
436	}
437	
438	/* ── Snake render ─────────────────────────────────────────────────────────── */
439	static void gop_draw_snake(void) {
440	    gop_draw_cell(gsx[0], gsy[0], S.head);
441	    for(int i=1;i<gslen;i++) gop_draw_cell(gsx[i],gsy[i],S.body);
442	}
443	
444	/* ── Init ─────────────────────────────────────────────────────────────────── */
445	static void gop_game_init(void) {
446	    rng_state ^= (uint32_t)timer_ticks;
447	    gslen=5; gdx=1; gdy=0; gdir=DIR_RIGHT;
448	    gscore=0; gpaused=0; gdead=0;
449	    int hx=G_cols/2, hy=G_rows/2;
450	    for(int i=0;i<gslen;i++){gsx[i]=hx-i;gsy[i]=hy;}
451	    gop_place_apple();
452	}
453	
454	/* ── Game step ────────────────────────────────────────────────────────────── */
455	static void gop_step(void) {
456	    int nx=gsx[0]+gdx, ny=gsy[0]+gdy;
457	    if(nx<0||nx>=G_cols||ny<0||ny>=G_rows){gdead=1;return;}
458	    for(int i=0;i<gslen;i++) if(gsx[i]==nx&&gsy[i]==ny){gdead=1;return;}
459	    int ate=(nx==gax&&ny==gay);
460	    if(!ate) gop_erase_cell(gsx[gslen-1],gsy[gslen-1]);
461	    int nl=ate?gslen+1:gslen; if(nl>GOP_MAX_LEN)nl=GOP_MAX_LEN;
462	    for(int i=nl-1;i>0;i--){gsx[i]=gsx[i-1];gsy[i]=gsy[i-1];}
463	    gsx[0]=nx;gsy[0]=ny;gslen=nl;
464	    if(ate){gscore++;gop_update_score();gop_place_apple();
465	        gop_draw_cell(gax,gay,S.fruit);}
466	    gop_draw_snake();
467	}
468	
469	/* ── Overlay: centered message box ────────────────────────────────────────── */
470	static void gop_msg_box(const char *line1, const char *line2, const char *line3) {
471	    uint32_t bw=260, bh=80;
472	    uint32_t bx=(G_bx+G_bw/2)-bw/2, by=(G_by+G_bh/2)-bh/2;
473	    fill(bx-4,by-4,bw+8,bh+8, S.border);
474	    fill(bx,by,bw,bh, S.bg);
475	    int cw1=strlen_s(line1), cw2=strlen_s(line2), cw3=strlen_s(line3);
476	    gop_text(bx+(bw-(uint32_t)cw1*8)/2, by+8,  line1, COL(C_LRED,   C_BLACK));
477	    gop_text(bx+(bw-(uint32_t)cw2*8)/2, by+30, line2, COL(C_YELLOW, C_BLACK));
478	    gop_text(bx+(bw-(uint32_t)cw3*8)/2, by+54, line3, COL(C_LGREY,  C_BLACK));
479	}
480	
481	/* ── Full repaint (scheme switch while paused) ────────────────────────────── */
482	static void gop_repaint_all(void) {
483	    fill(0, 0, G_fbw, G_fbh, S.bg);
484	    gop_draw_title();
485	    gop_draw_sidebar();
486	    gop_draw_border();
487	    fill(G_bx, G_by, G_bw, G_bh, S.bg);
488	    gop_draw_grid();
489	    gop_draw_cell(gax, gay, S.fruit);
490	    gop_draw_snake();
491	}
492	
493	/* ── Main GOP game loop ───────────────────────────────────────────────────── */
494	static void snake_gop(fb_info_t *fbi) {
495	    G_fbw = fbi->fb_width;
496	    G_fbh = fbi->fb_height;
497	
498	    /* Choose cell size so board fills ~85% of screen height */
499	    G_cell = 20;
500	    G_rows = (int)((G_fbh * 85 / 100) / G_cell);
501	    G_cols = G_rows * 3 / 2;          /* ~3:2 aspect */
502	    G_bw   = (uint32_t)G_cols * G_cell;
503	    G_bh   = (uint32_t)G_rows * G_cell;
504	
505	    /* Center board horizontally, leave room for sidebar on right */
506	    uint32_t sidebar_w = 160;
507	    G_sbx = G_fbw - sidebar_w;
508	    G_bx  = (G_sbx - G_bw) / 2;
509	    G_by  = (G_fbh - G_bh) / 2 + 8;
510	
511	    gbest = hs_load();
512	
513	    fill(0, 0, G_fbw, G_fbh, S.bg);
514	    gop_draw_title();
515	    gop_draw_sidebar();
516	    gop_draw_border();
517	    gop_draw_grid();
518	
519	    gop_game_init();
520	    gop_draw_cell(gax, gay, S.fruit);
521	    gop_draw_snake();
522	
523	    uint32_t last = (uint32_t)timer_ticks;
524	
525	    for(;;) {
526	        int k = (int)syscall0(SYS_GETKEY_NB);
527	        if (k >= 0) {
528	            if (k=='q'||k=='Q') { gdead=1; }
529	            else if (k=='c'||k=='C') {
530	                g_scheme = (g_scheme + 1) % NUM_SCHEMES;
531	                gop_repaint_all();
532	            } else if (k=='p'||k=='P') {
533	                gpaused ^= 1;
534	                if (gpaused)
535	                    gop_msg_box("  PAUSED  ", "P to resume", "C for colors");
536	                else {
537	                    fill(G_bx, G_by, G_bw, G_bh, S.bg);
538	                    gop_draw_grid();
539	                    gop_draw_cell(gax, gay, S.fruit);
540	                    gop_draw_snake();
541	                }
542	            } else {
543	                int nd = gdir;
544	                if((k=='w'||k=='W'||k==KEY_UP)   &&gdir!=DIR_DOWN) nd=DIR_UP;
545	                if((k=='s'||k=='S'||k==KEY_DOWN)  &&gdir!=DIR_UP)   nd=DIR_DOWN;
546	                if((k=='a'||k=='A'||k==KEY_LEFT)  &&gdir!=DIR_RIGHT)nd=DIR_LEFT;
547	                if((k=='d'||k=='D'||k==KEY_RIGHT) &&gdir!=DIR_LEFT) nd=DIR_RIGHT;
548	                if(nd!=gdir){gdir=nd;
549	                    if(gdir==DIR_UP){gdx=0;gdy=-1;}
550	                    else if(gdir==DIR_DOWN){gdx=0;gdy=1;}
551	                    else if(gdir==DIR_LEFT){gdx=-1;gdy=0;}
552	                    else{gdx=1;gdy=0;}
553	                }
554	            }
555	        }
556	        if (gdead) break;
557	        if (!gpaused) {
558	            uint32_t sp = 10;
559	            if(gscore>=15)sp=8; if(gscore>=30)sp=6; if(gscore>=50)sp=4;
560	            uint32_t now=(uint32_t)timer_ticks;
561	            if((uint32_t)(now-last)>=sp){last=now;gop_step();if(gdead)break;}
562	        }
563	        syscall0(SYS_YIELD);
564	    }
565	
566	    int nb=(gscore>gbest); if(nb){gbest=gscore;hs_save(gbest);}
567	
568	    char score_line[32];
569	    char best_line[32];
570	    /* build "Score: NN" */
571	    const char *sp="Score: "; int si=0;
572	    while(sp[si]){ score_line[si]=sp[si]; si++; }
573	    char snum[12]; itoa_s(gscore,snum);
574	    int sni=0; while(snum[sni]) score_line[si++]=snum[sni++]; score_line[si]='\0';
575	
576	    if (nb) {
577	        const char *bp="New best!"; int bi=0;
578	        while(bp[bi]){ best_line[bi]=bp[bi]; bi++; } best_line[bi]='\0';
579	    } else {
580	        const char *bp="Best: "; int bi=0;
581	        while(bp[bi]){ best_line[bi]=bp[bi]; bi++; }
582	        char bnum[12]; itoa_s(gbest,bnum);
583	        int bni=0; while(bnum[bni]) best_line[bi++]=bnum[bni++]; best_line[bi]='\0';
584	    }
585	
586	    gop_msg_box("GAME OVER", score_line, "Press any key");
587	    syscall0(SYS_GETKEY);
588	    fill(0, 0, G_fbw, G_fbh, S.bg);
589	}
590	
591	/* ════════════════════════════════════════════════════════════════════════════
592	 *  Entry point
593	 * ════════════════════════════════════════════════════════════════════════════*/
594	void snake_main(void) {
595	    fb_info_t fbi;
596	    syscall1(SYS_FB_INFO, (uint64_t)&fbi);
597	
598	    if (fbi.mode == 1)
599	        snake_gop(&fbi);
600	    else
601	        snake_vga();
602	}
