        var sRow = ROWS-1;
        if(!GOP) hline(0, sRow, COLS, WHITE, BLUE);
        else fill(0, sRow*CH, fbi.fbWidth, CH, rgb(0,0,0xAA));
        pokeStr(0, sRow, "  F5/r=refresh  q=quit  UP/DOWN=scroll", WHITE, BLUE);
    }

    /* ── Key codes ───────────────────────────────────────────────────────── */
    var KEY_Q    = 113;
    var KEY_R    = 114;
    var KEY_F5   = 0x13F;
    var KEY_UP   = 0x148;
    var KEY_DOWN = 0x150;

    /* ── Entry ───────────────────────────────────────────────────────────── */
    hideCursor();
    clearScreen();
    if(GOP) fbFillRect(0, 0, fbi.fbWidth, fbi.fbHeight, G_BG);
    render();

    var lastTick = getTicks();
    var REFRESH  = 100; /* ~1 s at 100 Hz */

    var running = true;
    while(running){
        var k = getKeyNonBlock();
        if(k !== -1){
            if(k === KEY_Q){
                running = false;
            } else if(k === KEY_DOWN){
                var p = getProcessList();
                if(scrollTop+PROC_ROWS < p.length) scrollTop++;
                render();
            } else if(k === KEY_UP){
                if(scrollTop>0) scrollTop--;
                render();
            } else if(k === KEY_R || k === KEY_F5){
                render();
            }
        }
        var now = getTicks();
        if(now - lastTick >= REFRESH){
            lastTick = now;
            render();
        }
    }

    showCursor();
    clearScreen();
    if(GOP) fbFillRect(0, 0, fbi.fbWidth, fbi.fbHeight, 0);
})();

