/* htop — dual-path process/memory monitor
 * VGA text mode: vgaPoke-based 80×25 TUI
 * GOP pixel mode: fbFillRect + vgaPoke character cells for a richer layout
 */
(function() {
    /* ── VGA palette indices ─────────────────────────────────────────────── */
    var BLACK=0, BLUE=1, GREEN=2, CYAN=3, RED=4, MAGENTA=5, BROWN=6, LGREY=7;
    var DGREY=8, LBLUE=9, LGREEN=10, LCYAN=11, LRED=12, LMAG=13, YELLOW=14, WHITE=15;

    /* ── GOP 32-bit colour packing  (mirrors gop_pack_color in C) ─────────
     * We pack as BGRX (blue low) which matches most QEMU firmware layouts.
     * The JS side cannot read the actual mask offsets, so we use 0x00RRGGBB
     * and let the kernel's fbFillRect path convert if needed — but since we
     * use the same packed format as snake (which passes raw 0xRRGGBB) we
     * match the convention used elsewhere in the codebase.           */
    function rgb(r,g,b){ return ((r&0xFF)<<16)|((g&0xFF)<<8)|(b&0xFF); }

    /* GOP colours */
    var G_BG       = rgb(0x0D,0x0D,0x1A);
    var G_HEADER   = rgb(0x00,0x44,0x22);
    var G_BAR_FILL = rgb(0x00,0xCC,0x44);
    var G_BAR_MEM  = rgb(0x22,0x88,0xFF);
    var G_BAR_EMPTY= rgb(0x1A,0x1A,0x2E);
    var G_BORDER   = rgb(0x22,0x44,0x22);
    var G_ROW_SEL  = rgb(0x00,0x22,0x44);
    var G_ROW_RUN  = rgb(0x00,0x33,0x11);

    /* ── Display info ────────────────────────────────────────────────────── */
    var fbi   = fbInfo();
    var GOP   = (fbi.mode === 1);
    var COLS  = GOP ? fbi.charCols : screenWidth();
    var ROWS  = GOP ? fbi.charRows : screenHeight();
    var CW    = fbi.cellW;   /* pixels per char cell (8) */
    var CH    = fbi.cellH;   /* pixels per char cell (16) */

    /* ── Low-level helpers ───────────────────────────────────────────────── */
    function atr(fg, bg){ return (bg<<4)|(fg&0xF); }

    function poke(col, row, ch, fg, bg){
        vgaPoke(col, row, ch.charCodeAt(0), atr(fg,bg));
    }
    function pokeStr(col, row, s, fg, bg){
        for(var i=0;i<s.length&&col+i<COLS;i++)
            vgaPoke(col+i, row, s.charCodeAt(i), atr(fg,bg));
    }
    function hline(col, row, w, fg, bg){
        for(var i=0;i<w&&col+i<COLS;i++)
            vgaPoke(col+i, row, 0x20, atr(fg,bg));
    }
    function fill(x,y,w,h,c){ if(GOP) fbFillRect(x,y,w,h,c); }

    /* pad/truncate to width */
    function fit(s,w){
        s=String(s);
        while(s.length<w) s=s+" ";
        if(s.length>w) s=s.substr(0,w);
        return s;
    }
    function rjust(s,w){
        s=String(s);
        while(s.length<w) s=" "+s;
        return s;
    }

    /* ── GOP background + header fills ──────────────────────────────────── */
    function gopBackground(){
        fill(0, 0, fbi.fbWidth, fbi.fbHeight, G_BG);
        /* header band row 0 */
        fill(0, 0, fbi.fbWidth, CH, G_HEADER);
        /* separator band row 3 */
        fill(0, 3*CH, fbi.fbWidth, 1, G_BORDER);
    }

    /* ── Bar renderer ────────────────────────────────────────────────────── */
    /* Text-mode bar: [||||      ] */
    function drawBarText(col, row, barW, used, total, fillFg){
        var filled = total>0 ? Math.floor((used/total)*barW) : 0;
        if(filled>barW) filled=barW;
        poke(col, row, "[", LGREY, BLACK);
        for(var i=0;i<barW;i++){
            if(i<filled) vgaPoke(col+1+i, row, 0x7C, atr(fillFg,BLACK));
            else         vgaPoke(col+1+i, row, 0x20, atr(DGREY,BLACK));
        }
        poke(col+1+barW, row, "]", LGREY, BLACK);
    }

    /* GOP bar: pixel rectangle */
    function drawBarGOP(col, row, barW, used, total, fillColor){
        var px = col*CW, py = row*CH;
        var filled = total>0 ? Math.floor((used/total)*barW) : 0;
        if(filled>barW) filled=barW;
        /* empty background */
        fill(px, py, barW*CW, CH-2, G_BAR_EMPTY);
        /* filled portion */
        if(filled>0) fill(px, py, filled*CW, CH-2, fillColor);
        /* border line */
        fill(px, py+CH-2, barW*CW, 1, G_BORDER);
    }

    function drawBar(col, row, barW, used, total, fillFg, fillColor){
        if(GOP) drawBarGOP(col, row, barW, used, total, fillColor);
        else    drawBarText(col, row, barW, used, total, fillFg);
    }

    /* ── State/ring labels ───────────────────────────────────────────────── */
    var STATE = ["unused","embryo","ready","running","blocked","zombie"];
    var RING  = ["kernel","service"];

    /* ── Scroll state ────────────────────────────────────────────────────── */
    var scrollTop = 0;
    /* leave rows: 0=title, 1=cpu, 2=mem, 3=header, 4..N=procs, N+1=scroll, N+2=status */
    var PROC_ROWS = ROWS - 6;
    if(PROC_ROWS < 4) PROC_ROWS = 4;

    /* ── Main render ─────────────────────────────────────────────────────── */
    function render(){
        var mem  = getMemInfo();
        var up   = getUptime();
        var proc = getProcessList();
        var tick = getTicks();

        if(GOP) gopBackground();

        /* ── Row 0: title bar ──────────────────────────────────────────── */
        if(!GOP) hline(0,0,COLS,BLACK,LGREEN);
        var title = " NephilimOS htop   [q=quit  UP/DOWN=scroll  r=refresh]";
        pokeStr(0, 0, title, GOP ? LGREEN : BLACK, GOP ? BLACK : LGREEN);
        var upStr = "up "+rjust(String(up),6)+"s ";
        pokeStr(COLS-upStr.length, 0, upStr, GOP ? YELLOW : BLACK, GOP ? BLACK : LGREEN);

        /* ── Row 1: CPU bar ────────────────────────────────────────────── */
        var cpuBarW = COLS - 18;
        var cpuLabel = "  CPU ";
        pokeStr(0, 1, cpuLabel, LGREEN, BLACK);
        var cpuFill = tick % (cpuBarW+1);
        drawBar(6, 1, cpuBarW, cpuFill, cpuBarW, LGREEN, G_BAR_FILL);
        var cpuPct = rjust(String(Math.floor(cpuFill/(cpuBarW)*100)),3)+"%";
        if(!GOP) pokeStr(7+cpuBarW, 1, cpuPct, WHITE, BLACK);
        else     pokeStr(7+cpuBarW, 1, cpuPct, WHITE, BLACK);

        /* ── Row 2: MEM bar ────────────────────────────────────────────── */
        var memBarW = COLS - 18;
        var memUsedMB  = Math.floor(mem.usedKB  / 1024);
        var memTotalMB = Math.floor(mem.totalKB / 1024);
        pokeStr(0, 2, "  Mem ", LGREEN, BLACK);
        drawBar(6, 2, memBarW, mem.usedKB, mem.totalKB, LBLUE, G_BAR_MEM);
        var memStr = rjust(String(memUsedMB),4)+"/"+fit(String(memTotalMB),4)+"M";
        pokeStr(7+memBarW, 2, memStr, WHITE, BLACK);

        /* ── Row 3: column header ──────────────────────────────────────── */
        if(!GOP) hline(0,3,COLS,DGREY,BLACK);
        else fill(0, 3*CH, fbi.fbWidth, CH, G_BORDER);
        pokeStr(0,  3, rjust("PID",5),    GOP ? LGREEN : LGREEN, BLACK);
        pokeStr(6,  3, fit("NAME",   16), GOP ? LGREEN : LGREEN, BLACK);
        pokeStr(23, 3, fit("RING",    7), GOP ? CYAN   : CYAN,   BLACK);
        pokeStr(31, 3, fit("STATE",   9), GOP ? YELLOW : YELLOW, BLACK);
        pokeStr(41, 3, fit("PRI",     4), GOP ? LGREY  : LGREY,  BLACK);

        /* ── Rows 4..4+PROC_ROWS-1: process list ──────────────────────── */
        for(var r=0; r<PROC_ROWS; r++){
            var row = 4+r;
            var idx = scrollTop+r;
            if(idx >= proc.length){
                hline(0, row, COLS, BLACK, BLACK);
                if(GOP) fill(0, row*CH, fbi.fbWidth, CH, G_BG);
                continue;
            }
            var p = proc[idx];
            var isRun = (p.state === 3);
            var rowFg = isRun ? LGREEN : WHITE;

            if(GOP){
                fill(0, row*CH, fbi.fbWidth, CH, isRun ? G_ROW_RUN : G_BG);
            } else {
                hline(0, row, COLS, rowFg, BLACK);
            }

            pokeStr(0,  row, rjust(String(p.pid), 5), rowFg, BLACK);
            pokeStr(6,  row, fit(p.name, 16),          rowFg, BLACK);
            var ringStr  = (p.ring<RING.length)  ? RING[p.ring]   : "?";
            var stateStr = (p.state<STATE.length)? STATE[p.state] : "?";
            pokeStr(23, row, fit(ringStr,  7), CYAN,               BLACK);
            pokeStr(31, row, fit(stateStr, 9), isRun ? LGREEN : YELLOW, BLACK);
            pokeStr(41, row, fit(String(p.priority), 4), LGREY,   BLACK);
        }

        /* ── Scroll indicator ──────────────────────────────────────────── */
        var scrollRow = 4+PROC_ROWS;
        if(!GOP) hline(0, scrollRow, COLS, DGREY, BLACK);
        else fill(0, scrollRow*CH, fbi.fbWidth, CH, G_BORDER);
        var cnt = proc.length;
        var endIdx = scrollTop + PROC_ROWS;
        if(endIdx>cnt) endIdx=cnt;
        var scrollMsg = "  Showing "+(scrollTop+1)+"-"+endIdx+" of "+cnt+" processes";
        pokeStr(0, scrollRow, scrollMsg, LGREY, BLACK);

        /* ── Status bar ────────────────────────────────────────────────── */
        var sRow = ROWS-1;
        if(!GOP) hline(0, sRow, COLS, WHITE, BLUE);
        else fill(0, sRow*CH, fbi.fbWidth, CH, rgb(0,0,0xAA));
        pokeStr(0, sRow, "  F5/r=refresh  q=quit  UP/DOWN=scroll", WHITE, BLUE);
    }

    /* ── Key codes ───────────────────────────────────────────────────────── */
    var KEY_Q    = 113;
    var KEY_R    = 114;
    var KEY_F5   = 0x13F;
    var KEY_UP   = 0x148;
    var KEY_DOWN = 0x150;

    /* ── Entry ───────────────────────────────────────────────────────────── */
    hideCursor();
    clearScreen();
    if(GOP) fbFillRect(0, 0, fbi.fbWidth, fbi.fbHeight, G_BG);
    render();

    var lastTick = getTicks();
    var REFRESH  = 100; /* ~1 s at 100 Hz */

    var running = true;
    while(running){
        var k = getKeyNonBlock();
        if(k !== -1){
            if(k === KEY_Q){
                running = false;
            } else if(k === KEY_DOWN){
                var p = getProcessList();
                if(scrollTop+PROC_ROWS < p.length) scrollTop++;
                render();
            } else if(k === KEY_UP){
                if(scrollTop>0) scrollTop--;
                render();
            } else if(k === KEY_R || k === KEY_F5){
                render();
            }
        }
        var now = getTicks();
        if(now - lastTick >= REFRESH){
            lastTick = now;
            render();
        }
    }

    showCursor();
    clearScreen();
    if(GOP) fbFillRect(0, 0, fbi.fbWidth, fbi.fbHeight, 0);
})();

