    const char *_s = (s); \
    while (*_s && p < end) *p++ = *_s++; \
} while(0)

    /* Export cwd so JS apps can resolve relative paths */
    EMIT("var __cwd=\"");
    if (cwd) {
        const char *c = cwd;
        while (*c && p < end) {
            if (*c == '\\' || *c == '"') { if (p < end) *p++ = '\\'; }
            if (p < end) *p++ = *c;
            c++;
        }
    } else {
        if (p < end) *p++ = '/';
    }
    EMIT("\";");

    EMIT("var __args=[");

    const char *tok = args_start;
    int first = 1;

    while (*tok) {
        while (*tok == ' ') tok++;
        if (!*tok) break;

        const char *te = tok;
        while (*te && *te != ' ') te++;

        if (!first) EMIT(",");
        first = 0;

        if (p < end) *p++ = '"';
        while (tok < te && p < end) {
            if (*tok == '\\' || *tok == '"') { if (p < end) *p++ = '\\'; }
            if (p < end) *p++ = *tok;
            tok++;
        }
        if (p < end) *p++ = '"';
        tok = te;
    }

    EMIT("];");
    *p = '\0';
    return (int)(p - buf);

#undef EMIT
}

