/* ── Seed table ─────────────────────────────────────────────────────────── */

typedef struct {
    const char *path;
    const char *src;
} seed_entry_t;

static const seed_entry_t seed_table[] = {
    { "/bin/ls",         seed_ls         },
    { "/bin/cat",        seed_cat        },
    { "/bin/touch",      seed_touch      },
    { "/bin/mkdir",      seed_mkdir      },
    { "/bin/rm",         seed_rm         },
    { "/bin/stat",       seed_stat       },
