42	void vga_cursor_enable(uint8_t cursor_start, uint8_t cursor_end) {
43	    outb(VGA_CRTC_INDEX, 0x0A);
44	    outb(VGA_CRTC_DATA,  (inb(VGA_CRTC_DATA) & 0xC0) | (cursor_start & 0x1F));
45	    outb(VGA_CRTC_INDEX, 0x0B);
46	    outb(VGA_CRTC_DATA,  (inb(VGA_CRTC_DATA) & 0xE0) | (cursor_end & 0x1F));
