119	/* ── GOP: convert a VGA palette index to a 32-bit GOP colour ───────────────── */
120	static uint32_t vga_pal_to_gop(uint8_t idx) {
121	    /* Standard VGA 16-colour palette in (R, G, B) */
122	    static const uint8_t pal[16][3] = {
123	        {0x00,0x00,0x00}, /* 0  black         */
124	        {0x00,0x00,0xAA}, /* 1  blue          */
125	        {0x00,0xAA,0x00}, /* 2  green         */
126	        {0x00,0xAA,0xAA}, /* 3  cyan          */
127	        {0xAA,0x00,0x00}, /* 4  red           */
128	        {0xAA,0x00,0xAA}, /* 5  magenta       */
129	        {0xAA,0x55,0x00}, /* 6  brown         */
130	        {0xAA,0xAA,0xAA}, /* 7  light grey    */
131	        {0x55,0x55,0x55}, /* 8  dark grey     */
132	        {0x55,0x55,0xFF}, /* 9  light blue    */
133	        {0x55,0xFF,0x55}, /* 10 light green   */
134	        {0x55,0xFF,0xFF}, /* 11 light cyan    */
135	        {0xFF,0x55,0x55}, /* 12 light red     */
136	        {0xFF,0x55,0xFF}, /* 13 light magenta */
137	        {0xFF,0xFF,0x55}, /* 14 yellow        */
138	        {0xFF,0xFF,0xFF}, /* 15 white         */
139	    };
140	    idx &= 0x0F;
141	    return gop_pack_color(pal[idx][0], pal[idx][1], pal[idx][2]);
