144	/* ── GOP text renderer: draw one glyph at the logical cursor position ──────── */
145	static void gop_render_char(char c, uint8_t attr) {
146	    uint32_t fg = vga_pal_to_gop(attr & 0x0F);
147	    uint32_t bg = vga_pal_to_gop((attr >> 4) & 0x0F);
