153	/* Erase a character cell to background colour */
154	static void gop_erase_cell(size_t col, size_t row) {
155	    uint32_t bg = vga_pal_to_gop((vga_color >> 4) & 0x0F);
156	    uint32_t px = (uint32_t)col * GOP_CELL_W;
157	    uint32_t py = (uint32_t)row * GOP_CELL_H;
158	    gop_fill_rect(px, py, GOP_CELL_W, GOP_CELL_H, bg);
