161	/* ── Logical grid dimensions ───────────────────────────────────────────────── */
162	static inline size_t grid_cols(void) {
163	    return use_gop_path ? (size_t)(gop_fb.width  / GOP_CELL_W) : (size_t)VGA_WIDTH;
164	}
165	static inline size_t grid_rows(void) {
166	    return use_gop_path ? (size_t)(gop_fb.height / GOP_CELL_H) : (size_t)VGA_HEIGHT;
167	}
