169	/* ── Scrolling ─────────────────────────────────────────────────────────────── */
170	static void vga_scroll(void) {
171	    size_t gc = grid_cols(), gr = grid_rows();
172	    if (!use_gop_path) {
173	        memmove((void *)VGA_ADDR,
174	                (const void *)(VGA_ADDR + gc),
175	                (gr - 1) * gc * sizeof(uint16_t));
176	        uint16_t blank = vga_entry(' ', vga_color);
177	        for (size_t col = 0; col < gc; col++)
178	            VGA_ADDR[(gr - 1) * gc + col] = blank;
179	    } else {
180	        uint32_t src_y = GOP_CELL_H;
181	        uint32_t copy_h = (uint32_t)(gr - 1) * GOP_CELL_H;
182	        uint32_t row_bytes = (uint32_t)gop_fb.width * (gop_fb.bpp / 8u);
183	        for (uint32_t y = 0; y < copy_h; y++) {
184	            volatile uint8_t *dst = (volatile uint8_t *)(uintptr_t)
185	                (gop_fb.addr + (uint64_t)y * gop_fb.pitch);
186	            volatile uint8_t *src = (volatile uint8_t *)(uintptr_t)
187	                (gop_fb.addr + (uint64_t)(src_y + y) * gop_fb.pitch);
188	            for (uint32_t x = 0; x < row_bytes; x++)
189	                dst[x] = src[x];
190	        }
191	        uint32_t bg = vga_pal_to_gop((vga_color >> 4) & 0x0F);
192	        gop_fill_rect(0, (uint32_t)(gr - 1) * GOP_CELL_H,
193	                      gop_fb.width, GOP_CELL_H, bg);
194	    }
195	    vga_row = gr - 1;
196	}
197	
198	/* ── Screen clear ──────────────────────────────────────────────────────────── */
199	void vga_clear(void) {
200	    if (!use_gop_path) {
201	        for (size_t i = 0; i < VGA_WIDTH * VGA_HEIGHT; i++)
202	            VGA_ADDR[i] = vga_entry(' ', vga_color);
203	        vga_cursor_move(0, 0);
204	    } else {
205	        uint32_t bg = vga_pal_to_gop((vga_color >> 4) & 0x0F);
206	        gop_clear(bg);
207	    }
208	    vga_col = 0;
209	    vga_row = 0;
210	}
211	
212	/* ── Logical cursor ────────────────────────────────────────────────────────── */
213	
214	void vga_goto(size_t col, size_t row) {
215	    size_t gc = grid_cols(), gr = grid_rows();
216	    if (col >= gc) col = gc - 1;
217	    if (row >= gr) row = gr - 1;
218	    vga_col = col;
219	    vga_row = row;
220	    if (!use_gop_path) vga_cursor_move(col, row);
221	}
222	
223	/* ── Character output ──────────────────────────────────────────────────────── */
224	static void vga_putchar(char c) {
225	    size_t gc = grid_cols(), gr = grid_rows();
226	    if (c == '\n') {
227	        vga_col = 0;
228	        if (++vga_row >= gr) vga_scroll();
229	        return;
230	    }
231	    if (c == '\r') { vga_col = 0; return; }
232	    if (c == '\t') {
233	        vga_col = (vga_col + 8) & ~7u;
234	        if (vga_col >= gc) {
235	            vga_col = 0;
236	            if (++vga_row >= gr) vga_scroll();
237	        }
238	        return;
239	    }
240	    if (c == '\b') {
241	        if (vga_col > 0) vga_col--;
242	        if (!use_gop_path)
243	            VGA_ADDR[vga_row * gc + vga_col] = vga_entry(' ', vga_color);
244	        else
245	            gop_erase_cell(vga_col, vga_row);
246	        return;
247	    }
248	
249	    if (!use_gop_path) {
250	        VGA_ADDR[vga_row * gc + vga_col] = vga_entry(c, vga_color);
251	    } else {
252	        gop_render_char(c, vga_color);
253	    }
254	
255	    if (++vga_col >= gc) {
256	        vga_col = 0;
257	        if (++vga_row >= gr) vga_scroll();
258	    }
259	}
260	
261	/* ── Print API ─────────────────────────────────────────────────────────────── */
262	void kprint_char(char c) {
263	    vga_putchar(c);
264	    if (!use_gop_path) vga_cursor_move(vga_col, vga_row);
265	}
266	
267	void kprint(const char *str) {
268	    serial_print(str);
269	    for (size_t i = 0; str[i]; i++)
270	        vga_putchar(str[i]);
271	    if (!use_gop_path) vga_cursor_move(vga_col, vga_row);
272	}
273	
274	void kprint_color(const char *str, uint8_t color) {
275	    uint8_t saved = vga_color;
276	    vga_color = color;
277	    kprint(str);
278	    vga_color = saved;
279	}
280	
281	void kprint_uint64(uint64_t n) {
282	    if (n == 0) { kprint("0"); return; }
283	    char buf[21]; int i = 20; buf[i] = '\0';
284	    while (n) { buf[--i] = '0' + (int)(n % 10); n /= 10; }
285	    kprint(buf + i);
286	}
287	
288	void kprint_hex(uint64_t n) {
289	    static const char hex[] = "0123456789ABCDEF";
290	    char buf[19]; buf[0]='0'; buf[1]='x'; int i = 18; buf[i] = '\0';
291	    if (n == 0) { kprint("0x0"); return; }
292	    while (n) { buf[--i] = hex[n & 0xF]; n >>= 4; }
293	    kprint(buf + i - 2);
294	}
