for (;;) {
    var key = getChar();

    if (key === 3) {                              /* Ctrl+C — quit */
        if (confirmQuit()) break;

    } else if (key === 19) {                      /* Ctrl+S — save */
        saveFile();

    } else if (key === 11) {                      /* Ctrl+K — delete line */
        deleteLine();

    } else if (key === 1) {                       /* Ctrl+A — top of file */
        batch(function() { cy.set(0); cx.set(0); top.set(0); });

    } else if (key === 5) {                       /* Ctrl+E — end of file */
        var lastRow = lines.length - 1;
        batch(function() { cy.set(lastRow); cx.set(lines[lastRow].length); });

    } else if (key === KEY_UP) {
        var row = cy.peek();
        if (row > 0) batch(function() {
            var nr = row - 1;
            cy.set(nr); cx.set(clamp(cx.peek(), 0, lines[nr].length));
        });

    } else if (key === KEY_DOWN) {
        var row = cy.peek();
        if (row < lines.length - 1) batch(function() {
            var nr = row + 1;
            cy.set(nr); cx.set(clamp(cx.peek(), 0, lines[nr].length));
        });

    } else if (key === KEY_LEFT) {
        batch(function() {
            var col = cx.peek(); var row = cy.peek();
            if (col > 0)       cx.set(col - 1);
            else if (row > 0) { cy.set(row - 1); cx.set(lines[row - 1].length); }
        });

    } else if (key === KEY_RIGHT) {
        batch(function() {
            var col = cx.peek(); var row = cy.peek();
            if (col < lines[row].length)            cx.set(col + 1);
            else if (row < lines.length - 1) { cy.set(row + 1); cx.set(0); }
        });

    } else if (key === KEY_HOME) {
        cx.set(0);

    } else if (key === KEY_END) {
        cx.set(lines[cy.peek()].length);

    } else if (key === KEY_PGUP) {
        batch(function() {
            var nr = clamp(cy.peek() - ROWS, 0, lines.length - 1);
            cy.set(nr); cx.set(clamp(cx.peek(), 0, lines[nr].length));
        });

