var running = true;
while(running){
    var k = getKeyNonBlock();
    if(k !== -1){
        if(k === KEY_Q){
            running = false;
        } else if(k === KEY_DOWN){
            var p = getProcessList();
            if(scrollTop+PROC_ROWS < p.length) scrollTop++;
            render();
        } else if(k === KEY_UP){
            if(scrollTop>0) scrollTop--;
            render();
        } else if(k === KEY_R || k === KEY_F5){
            render();
        }
    }
    var now = getTicks();
    if(now - lastTick >= REFRESH){
        lastTick = now;
        render();
    }
}

input.new_string:
var running = true;
while(running){
    /* Blocking wait for next keypress or timeout — avoids busy-spin
     * that can exhaust MuJS's internal call stack / trigger GC issues. */
    var k = getChar();  /* blocks until a key arrives */
    if(k === KEY_Q){
        running = false;
    } else if(k === KEY_DOWN){
        var p = getProcessList();
        if(scrollTop+PROC_ROWS < p.length) scrollTop++;
        render();
    } else if(k === KEY_UP){
        if(scrollTop>0) scrollTop--;
        render();
    } else if(k === KEY_R || k === KEY_F5 || k === 13 /* Enter */){
        render();
    }
    /* Any other key also refreshes */
    else { render(); }
}

